// ─────────────────────────────────────────────────────────────────────────────
// PariLink Mobile — Root Navigation
// Stack + Bottom Tabs navigator wired to the full screen inventory.
// Handles auth-gating: unauthenticated → Auth stack; authenticated → Main tabs.
// ─────────────────────────────────────────────────────────────────────────────

import React from 'react';
import { useColorScheme } from 'react-native';
import { NavigationContainer, DefaultTheme, DarkTheme as NavDarkTheme } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';

import { useAppSelector } from '../store';
import { LightTheme, DarkTheme } from '../theme';

import type { RootStackParamList, TabParamList } from '../types';

// ── Auth Screens ──────────────────────────────────────────────────────────────
import { LoginScreen }         from '../screens/auth/LoginScreen';

// ── Main Tab Screens ──────────────────────────────────────────────────────────
import { DashboardScreen }     from '../screens/dashboard/DashboardScreen';
import { TripDetailScreen }    from '../screens/trips/TripDetailScreen';
import { DocumentCameraScreen }from '../screens/documents/DocumentCameraScreen';
import { ExpenseFormScreen }   from '../screens/expenses/ExpenseFormScreen';
import { EmergencySOSScreen }  from '../screens/emergency/EmergencySOSScreen';

const Stack = createNativeStackNavigator<RootStackParamList>();
const Tab   = createBottomTabNavigator<TabParamList>();

// ─── Bottom Tab Navigator ──────────────────────────────────────────────────────
function MainTabs() {
  const scheme = useColorScheme();
  const theme  = scheme === 'dark' ? DarkTheme : LightTheme;

  const TAB_ICONS: Record<string, { active: string; inactive: string }> = {
    Dashboard: { active: '🏠', inactive: '🏚' },
    Trips:     { active: '🚛', inactive: '🚚' },
    Documents: { active: '📂', inactive: '📁' },
    Finance:   { active: '💰', inactive: '💸' },
    More:      { active: '☰',  inactive: '☰' },
  };

  return (
    <Tab.Navigator
      screenOptions={({ route }) => ({
        tabBarIcon: ({ focused }) => {
          const icons = TAB_ICONS[route.name] ?? { active: '•', inactive: '•' };
          return <>{focused ? icons.active : icons.inactive}</>;
        },
        tabBarActiveTintColor:   theme.tabBarActive,
        tabBarInactiveTintColor: theme.tabBarInactive,
        tabBarStyle: {
          backgroundColor: theme.tabBar,
          borderTopColor:  theme.tabBarBorder,
          borderTopWidth:  1,
          height:          Platform.OS === 'ios' ? 80 : 60,
          paddingBottom:   Platform.OS === 'ios' ? 20 : 8,
        },
        tabBarLabelStyle: { fontSize: 11, fontWeight: '600' },
        headerStyle:      { backgroundColor: theme.header },
        headerTintColor:  theme.headerText,
        headerTitleStyle: { fontWeight: '700', fontSize: 18 },
      })}
    >
      <Tab.Screen name="Dashboard" component={DashboardScreen} options={{ title: 'Home' }} />
      <Tab.Screen name="Trips"     component={DashboardScreen} options={{ title: 'Trips' }} />
      <Tab.Screen name="Documents" component={DashboardScreen} options={{ title: 'Docs' }} />
      <Tab.Screen name="Finance"   component={DashboardScreen} options={{ title: 'Finance' }} />
      <Tab.Screen name="More"      component={DashboardScreen} options={{ title: 'More' }} />
    </Tab.Navigator>
  );
}

// ─── Root Navigator ────────────────────────────────────────────────────────────
export function AppNavigator() {
  const scheme      = useColorScheme();
  const theme       = scheme === 'dark' ? DarkTheme : LightTheme;
  const accessToken = useAppSelector((s) => s.auth.accessToken);

  const navTheme = {
    ...(scheme === 'dark' ? NavDarkTheme : DefaultTheme),
    colors: {
      ...(scheme === 'dark' ? NavDarkTheme : DefaultTheme).colors,
      background: theme.background,
      card:       theme.header,
      text:       theme.headerText,
      border:     theme.border,
    },
  };

  return (
    <NavigationContainer theme={navTheme}>
      <Stack.Navigator
        screenOptions={{
          headerStyle:     { backgroundColor: theme.header },
          headerTintColor: theme.headerText,
          headerTitleStyle: { fontWeight: '700', fontSize: 18 },
          animation:       'ios_from_right',
        }}
      >
        {!accessToken ? (
          // ── Auth Stack ────────────────────────────────────────────────────
          <Stack.Screen name="Login" component={LoginScreen} options={{ headerShown: false }} />
        ) : (
          // ── Authenticated Stack ───────────────────────────────────────────
          <>
            <Stack.Screen name="MainTabs" component={MainTabs} options={{ headerShown: false }} />
            <Stack.Screen name="TripDetail" component={TripDetailScreen} options={{ title: 'Trip Details' }} />
            <Stack.Screen name="DocumentCamera" component={DocumentCameraScreen} options={{ title: 'Upload Document' }} />
            <Stack.Screen name="ExpenseForm" component={ExpenseFormScreen} options={{ title: 'Log Expense' }} />
            <Stack.Screen name="EmergencySOS" component={EmergencySOSScreen} options={{ headerShown: false }} />
          </>
        )}
      </Stack.Navigator>
    </NavigationContainer>
  );
}

// ── Missing Platform import fix
import { Platform } from 'react-native';

// ─────────────────────────────────────────────────────────────────────────────
// PariLink Mobile — Login Screen
// Email/password + OTP toggle + biometric shortcut.
// Dark/Light theme aware. Animated entry. Form validation via react-hook-form.
// ─────────────────────────────────────────────────────────────────────────────

import React, { useCallback, useEffect, useRef, useState } from 'react';
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  StyleSheet,
  Animated,
  Platform,
  KeyboardAvoidingView,
  ScrollView,
  ActivityIndicator,
  Alert,
} from 'react-native';
import { useForm, Controller } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import type { NativeStackNavigationProp } from '@react-navigation/native-stack';
import type { RootStackParamList } from '../../types';
import { useAppDispatch, useAppSelector } from '../../store';
import { loginThunk, biometricLoginThunk, setBiometricAvailable } from '../../store/slices/authSlice';
import { BiometricService } from '../../services/biometric/BiometricService';
import { LightTheme, DarkTheme, Typography, Spacing, Radius } from '../../theme';
import { useColorScheme } from 'react-native';

// ─── Validation ───────────────────────────────────────────────────────────────
const loginSchema = z.object({
  email:    z.string().email('Enter a valid email'),
  password: z.string().min(6, 'Password must be at least 6 characters'),
});
type LoginForm = z.infer<typeof loginSchema>;

// ─── Props ────────────────────────────────────────────────────────────────────
interface Props {
  navigation: NativeStackNavigationProp<RootStackParamList, 'Login'>;
}

export function LoginScreen({ navigation }: Props) {
  const scheme   = useColorScheme();
  const theme    = scheme === 'dark' ? DarkTheme : LightTheme;
  const dispatch = useAppDispatch();

  const { isLoading, biometricAvailable } = useAppSelector((s) => s.auth);

  const [biometryLabel, setBiometryLabel] = useState('Biometrics');
  const [showPassword, setShowPassword]   = useState(false);

  const fadeAnim  = useRef(new Animated.Value(0)).current;
  const slideAnim = useRef(new Animated.Value(40)).current;

  const { control, handleSubmit, formState: { errors } } = useForm<LoginForm>({
    resolver: zodResolver(loginSchema),
  });

  // ── Boot animation ──────────────────────────────────────────────────────────
  useEffect(() => {
    Animated.parallel([
      Animated.timing(fadeAnim,  { toValue: 1, duration: 600, useNativeDriver: true }),
      Animated.timing(slideAnim, { toValue: 0, duration: 500, useNativeDriver: true }),
    ]).start();
  }, []);

  // ── Check biometric availability ────────────────────────────────────────────
  useEffect(() => {
    (async () => {
      const { available, biometryType } = await BiometricService.isAvailable();
      dispatch(setBiometricAvailable(available));
      setBiometryLabel(BiometricService.getBiometryLabel(biometryType));
    })();
  }, []);

  // ── Handlers ─────────────────────────────────────────────────────────────────
  const onSubmit = useCallback(async (data: LoginForm) => {
    const result = await dispatch(loginThunk(data));
    if (loginThunk.rejected.match(result)) {
      Alert.alert('Login Failed', result.payload as string);
    }
  }, [dispatch]);

  const onBiometric = useCallback(async () => {
    const success = await BiometricService.authenticate('Login to PariLink');
    if (success) {
      const result = await dispatch(biometricLoginThunk());
      if (biometricLoginThunk.rejected.match(result)) {
        Alert.alert('Session Expired', 'Please login with your credentials.');
      }
    }
  }, [dispatch]);

  const styles = makeStyles(theme);

  return (
    <KeyboardAvoidingView
      style={[styles.container]}
      behavior={Platform.OS === 'ios' ? 'padding' : undefined}
    >
      <ScrollView
        contentContainerStyle={styles.scroll}
        keyboardShouldPersistTaps="handled"
        showsVerticalScrollIndicator={false}
      >
        {/* ── Brand ─────────────────────────────────────────────────────────── */}
        <Animated.View style={[styles.brandSection, { opacity: fadeAnim, transform: [{ translateY: slideAnim }] }]}>
          <View style={styles.logoContainer}>
            <Text style={styles.logoText}>P</Text>
          </View>
          <Text style={styles.brandName}>PariLink</Text>
          <Text style={styles.tagline}>Enterprise Logistics Platform</Text>
        </Animated.View>

        {/* ── Form ──────────────────────────────────────────────────────────── */}
        <Animated.View style={[styles.formCard, { opacity: fadeAnim }]}>
          <Text style={styles.formTitle}>Driver Login</Text>
          <Text style={styles.formSubtitle}>Sign in to your account to continue</Text>

          {/* Email */}
          <View style={styles.fieldGroup}>
            <Text style={styles.label}>Email Address</Text>
            <Controller
              control={control}
              name="email"
              render={({ field: { onChange, onBlur, value } }) => (
                <TextInput
                  style={[styles.input, errors.email && styles.inputError]}
                  value={value}
                  onChangeText={onChange}
                  onBlur={onBlur}
                  placeholder="driver@company.com"
                  placeholderTextColor={theme.inputPlaceholder}
                  autoCapitalize="none"
                  keyboardType="email-address"
                  autoComplete="email"
                  returnKeyType="next"
                  accessibilityLabel="Email address input"
                />
              )}
            />
            {errors.email && <Text style={styles.errorText}>{errors.email.message}</Text>}
          </View>

          {/* Password */}
          <View style={styles.fieldGroup}>
            <Text style={styles.label}>Password</Text>
            <View style={styles.passwordContainer}>
              <Controller
                control={control}
                name="password"
                render={({ field: { onChange, onBlur, value } }) => (
                  <TextInput
                    style={[styles.input, styles.passwordInput, errors.password && styles.inputError]}
                    value={value}
                    onChangeText={onChange}
                    onBlur={onBlur}
                    placeholder="Enter your password"
                    placeholderTextColor={theme.inputPlaceholder}
                    secureTextEntry={!showPassword}
                    returnKeyType="done"
                    onSubmitEditing={handleSubmit(onSubmit)}
                    accessibilityLabel="Password input"
                  />
                )}
              />
              <TouchableOpacity
                style={styles.eyeButton}
                onPress={() => setShowPassword((v) => !v)}
                accessibilityLabel={showPassword ? 'Hide password' : 'Show password'}
              >
                <Text style={styles.eyeIcon}>{showPassword ? '👁' : '👁‍🗨'}</Text>
              </TouchableOpacity>
            </View>
            {errors.password && <Text style={styles.errorText}>{errors.password.message}</Text>}
          </View>

          {/* Login Button */}
          <TouchableOpacity
            style={[styles.loginBtn, isLoading && styles.loginBtnDisabled]}
            onPress={handleSubmit(onSubmit)}
            disabled={isLoading}
            accessibilityRole="button"
            accessibilityLabel="Login button"
            activeOpacity={0.85}
          >
            {isLoading
              ? <ActivityIndicator color="#FFFFFF" size="small" />
              : <Text style={styles.loginBtnText}>Sign In</Text>
            }
          </TouchableOpacity>

          {/* Biometric */}
          {biometricAvailable && (
            <TouchableOpacity
              style={styles.biometricBtn}
              onPress={onBiometric}
              accessibilityRole="button"
              accessibilityLabel={`Login with ${biometryLabel}`}
              activeOpacity={0.8}
            >
              <Text style={styles.biometricText}>🔐  Login with {biometryLabel}</Text>
            </TouchableOpacity>
          )}
        </Animated.View>

        {/* ── Footer ───────────────────────────────────────────────────────── */}
        <Text style={styles.footer}>
          Secured by PariLink Enterprise Security
        </Text>
      </ScrollView>
    </KeyboardAvoidingView>
  );
}

// ─── Styles ───────────────────────────────────────────────────────────────────
function makeStyles(theme: typeof LightTheme) {
  return StyleSheet.create({
    container: {
      flex: 1,
      backgroundColor: theme.background,
    },
    scroll: {
      flexGrow:        1,
      paddingHorizontal: Spacing.lg,
      paddingTop:        Spacing.xxxl,
      paddingBottom:     Spacing.xl,
    },
    brandSection: {
      alignItems:   'center',
      marginBottom: Spacing.xl,
    },
    logoContainer: {
      width:           72,
      height:          72,
      borderRadius:    Radius.lg,
      backgroundColor: theme.primary,
      justifyContent:  'center',
      alignItems:      'center',
      marginBottom:    Spacing.md,
      shadowColor:     theme.primary,
      shadowOffset:    { width: 0, height: 8 },
      shadowOpacity:   0.4,
      shadowRadius:    16,
      elevation:       10,
    },
    logoText: {
      ...Typography.displayLG,
      color:      '#FFFFFF',
      fontWeight: '900',
    },
    brandName: {
      ...Typography.displayMD,
      color:        theme.text,
      marginBottom: Spacing.xs,
    },
    tagline: {
      ...Typography.bodyMD,
      color: theme.textSecondary,
    },
    formCard: {
      backgroundColor: theme.surface,
      borderRadius:    Radius.xl,
      padding:         Spacing.lg,
      marginBottom:    Spacing.lg,
      shadowColor:     theme.cardShadow,
      shadowOffset:    { width: 0, height: 4 },
      shadowOpacity:   1,
      shadowRadius:    16,
      elevation:       6,
    },
    formTitle: {
      ...Typography.headingLG,
      color:        theme.text,
      marginBottom: Spacing.xs,
    },
    formSubtitle: {
      ...Typography.bodyMD,
      color:        theme.textSecondary,
      marginBottom: Spacing.lg,
    },
    fieldGroup: {
      marginBottom: Spacing.md,
    },
    label: {
      ...Typography.labelMD,
      color:        theme.textSecondary,
      marginBottom: Spacing.xs,
      textTransform: 'uppercase',
      letterSpacing: 0.5,
    },
    input: {
      backgroundColor:  theme.input,
      borderWidth:      1.5,
      borderColor:      theme.inputBorder,
      borderRadius:     Radius.md,
      paddingHorizontal: Spacing.md,
      paddingVertical:   Platform.OS === 'ios' ? 14 : 12,
      ...Typography.bodyLG,
      color:            theme.inputText,
    },
    inputError: {
      borderColor: theme.danger,
    },
    passwordContainer: {
      position: 'relative',
    },
    passwordInput: {
      paddingRight: 48,
    },
    eyeButton: {
      position: 'absolute',
      right:    Spacing.md,
      top:      0,
      bottom:   0,
      justifyContent: 'center',
    },
    eyeIcon: {
      fontSize: 18,
    },
    errorText: {
      ...Typography.caption,
      color:      theme.danger,
      marginTop:  Spacing.xs,
    },
    loginBtn: {
      backgroundColor:  theme.primary,
      borderRadius:     Radius.md,
      paddingVertical:  16,
      alignItems:       'center',
      justifyContent:   'center',
      marginTop:        Spacing.sm,
      shadowColor:      theme.primary,
      shadowOffset:     { width: 0, height: 4 },
      shadowOpacity:    0.4,
      shadowRadius:     8,
      elevation:        6,
    },
    loginBtnDisabled: {
      opacity: 0.6,
    },
    loginBtnText: {
      ...Typography.labelLG,
      color:        '#FFFFFF',
      fontSize:     16,
      letterSpacing: 0.5,
    },
    biometricBtn: {
      marginTop:       Spacing.md,
      paddingVertical: 14,
      alignItems:      'center',
      borderRadius:    Radius.md,
      borderWidth:     1.5,
      borderColor:     theme.border,
    },
    biometricText: {
      ...Typography.labelMD,
      color:     theme.primary,
      fontSize:  14,
    },
    footer: {
      ...Typography.caption,
      color:     theme.textTertiary,
      textAlign: 'center',
      marginTop: Spacing.lg,
    },
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// PariLink Mobile — Driver Dashboard Screen
// Shows: Active trip card, earnings summary, today's tasks, offline banner.
// Real-time refresh (30s interval). Offline-aware. Dark/Light theme.
// ─────────────────────────────────────────────────────────────────────────────

import React, { useCallback, useEffect, useRef, useState } from 'react';
import {
  View,
  Text,
  ScrollView,
  StyleSheet,
  TouchableOpacity,
  RefreshControl,
  useColorScheme,
  Animated,
  Platform,
} from 'react-native';
import type { NativeStackNavigationProp } from '@react-navigation/native-stack';
import { useFocusEffect } from '@react-navigation/native';
import type { RootStackParamList } from '../../types';
import { useAppDispatch, useAppSelector } from '../../store';
import { fetchActiveTripThunk } from '../../store/slices/tripsSlice';
import { fetchNotificationsThunk } from '../../store/slices/notificationsSlice';
import { OfflineQueue } from '../../offline/OfflineQueue';
import { setPendingQueueCount } from '../../store/slices/uiSlice';
import { LightTheme, DarkTheme, Typography, Spacing, Radius } from '../../theme';
import { TripStatusChip } from '../../components/trips/TripStatusChip';
import { OfflineBanner } from '../../components/common/OfflineBanner';

interface Props {
  navigation: NativeStackNavigationProp<RootStackParamList, 'MainTabs'>;
}

const REFRESH_INTERVAL_MS = 30_000;

export function DashboardScreen({ navigation }: Props) {
  const scheme   = useColorScheme();
  const theme    = scheme === 'dark' ? DarkTheme : LightTheme;
  const dispatch = useAppDispatch();

  const user              = useAppSelector((s) => s.auth.user);
  const activeTrip        = useAppSelector((s) => s.trips.activeTrip);
  const isOnline          = useAppSelector((s) => s.offline.isOnline);
  const pendingQueueCount = useAppSelector((s) => s.ui.pendingQueueCount);
  const unreadCount       = useAppSelector((s) => s.notifications.unreadCount);

  const [refreshing, setRefreshing] = useState(false);
  const pulseAnim  = useRef(new Animated.Value(1)).current;
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // ── Pulse animation for active trip indicator ────────────────────────────────
  useEffect(() => {
    if (activeTrip?.status === 'IN_PROGRESS') {
      const pulse = Animated.loop(
        Animated.sequence([
          Animated.timing(pulseAnim, { toValue: 1.1, duration: 800, useNativeDriver: true }),
          Animated.timing(pulseAnim, { toValue: 1.0, duration: 800, useNativeDriver: true }),
        ]),
      );
      pulse.start();
      return () => pulse.stop();
    }
  }, [activeTrip?.status]);

  // ── Data refresh ─────────────────────────────────────────────────────────────
  const refresh = useCallback(async () => {
    await Promise.all([
      dispatch(fetchActiveTripThunk()),
      dispatch(fetchNotificationsThunk()),
    ]);
    const count = await OfflineQueue.count();
    dispatch(setPendingQueueCount(count));
  }, [dispatch]);

  useFocusEffect(useCallback(() => {
    refresh();
    intervalRef.current = setInterval(refresh, REFRESH_INTERVAL_MS);
    return () => {
      if (intervalRef.current) {clearInterval(intervalRef.current);}
    };
  }, [refresh]));

  const onRefresh = async () => {
    setRefreshing(true);
    await refresh();
    setRefreshing(false);
  };

  const styles = makeStyles(theme);

  // ── Greeting ─────────────────────────────────────────────────────────────────
  const hour = new Date().getHours();
  const greeting = hour < 12 ? 'Good morning' : hour < 17 ? 'Good afternoon' : 'Good evening';

  return (
    <ScrollView
      style={styles.container}
      contentContainerStyle={styles.content}
      showsVerticalScrollIndicator={false}
      refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor={theme.primary} />}
    >
      {/* ── Offline Banner ─────────────────────────────────────────────────── */}
      {!isOnline && <OfflineBanner queueCount={pendingQueueCount} />}

      {/* ── Header ────────────────────────────────────────────────────────── */}
      <View style={styles.header}>
        <View>
          <Text style={styles.greeting}>{greeting} 👋</Text>
          <Text style={styles.driverName}>{user?.name ?? 'Driver'}</Text>
        </View>
        <TouchableOpacity
          style={styles.notifButton}
          onPress={() => navigation.navigate('Notifications')}
          accessibilityLabel={`Notifications — ${unreadCount} unread`}
        >
          <Text style={styles.notifIcon}>🔔</Text>
          {unreadCount > 0 && (
            <View style={styles.badge}>
              <Text style={styles.badgeText}>
                {unreadCount > 9 ? '9+' : String(unreadCount)}
              </Text>
            </View>
          )}
        </TouchableOpacity>
      </View>

      {/* ── Active Trip Card ──────────────────────────────────────────────── */}
      {activeTrip ? (
        <TouchableOpacity
          style={styles.activeTripCard}
          onPress={() => navigation.navigate('TripDetail', { tripId: activeTrip.id })}
          activeOpacity={0.92}
          accessibilityRole="button"
          accessibilityLabel={`Active trip ${activeTrip.tripNo} — tap to view details`}
        >
          <View style={styles.activeTripHeader}>
            <View>
              <Text style={styles.activeTripLabel}>ACTIVE TRIP</Text>
              <Text style={styles.activeTripNo}>{activeTrip.tripNo}</Text>
            </View>
            <Animated.View style={[styles.liveDot, { transform: [{ scale: pulseAnim }] }]} />
          </View>

          <View style={styles.routeRow}>
            <View style={styles.routePoint}>
              <View style={[styles.dot, { backgroundColor: theme.primary }]} />
              <Text style={styles.routeText} numberOfLines={1}>
                {activeTrip.loads[0]?.origin ?? '—'}
              </Text>
            </View>
            <View style={styles.routeLine} />
            <View style={styles.routePoint}>
              <View style={[styles.dot, { backgroundColor: theme.success }]} />
              <Text style={styles.routeText} numberOfLines={1}>
                {activeTrip.loads[activeTrip.loads.length - 1]?.destination ?? '—'}
              </Text>
            </View>
          </View>

          <View style={styles.activeTripFooter}>
            <TripStatusChip status={activeTrip.status} />
            <Text style={styles.vehicleText}>{activeTrip.vehicle.regNo}</Text>
          </View>
        </TouchableOpacity>
      ) : (
        <View style={styles.noTripCard}>
          <Text style={styles.noTripIcon}>🚛</Text>
          <Text style={styles.noTripTitle}>No Active Trip</Text>
          <Text style={styles.noTripSubtitle}>
            Your dispatcher will assign your next trip here.
          </Text>
        </View>
      )}

      {/* ── Today's Summary ───────────────────────────────────────────────── */}
      <Text style={styles.sectionTitle}>Today's Summary</Text>
      <View style={styles.statsRow}>
        <StatCard theme={theme} icon="📦" label="Loads" value={String(activeTrip?.loads.length ?? 0)} />
        <StatCard theme={theme} icon="📍" label="Status" value={activeTrip?.status ?? 'Idle'} />
        <StatCard theme={theme} icon="🚗" label="Vehicle" value={activeTrip?.vehicle.vehicleType ?? '—'} />
      </View>

      {/* ── Quick Actions ─────────────────────────────────────────────────── */}
      <Text style={styles.sectionTitle}>Quick Actions</Text>
      <View style={styles.actionsGrid}>
        <QuickAction
          theme={theme}
          icon="📷"
          label="Upload POD"
          onPress={() => activeTrip && navigation.navigate('DocumentCamera', {
            type: 'POD',
            referenceId: activeTrip.loads[0]?.id ?? '',
          })}
        />
        <QuickAction
          theme={theme}
          icon="⛽"
          label="Log Fuel"
          onPress={() => activeTrip && navigation.navigate('ExpenseForm', {
            tripId: activeTrip.id,
            prefillCategory: 'FUEL',
          })}
        />
        <QuickAction
          theme={theme}
          icon="🔍"
          label="Inspection"
          onPress={() => activeTrip && navigation.navigate('Inspection', {
            vehicleId: activeTrip.vehicle.id,
            tripId:    activeTrip.id,
            type:      'PRE_TRIP',
          })}
        />
        <QuickAction
          theme={theme}
          icon="🆘"
          label="SOS"
          onPress={() => navigation.navigate('EmergencySOS')}
          danger
        />
      </View>

      {/* ── Offline Queue Indicator ─────────────────────────────────────── */}
      {pendingQueueCount > 0 && (
        <View style={styles.queueCard}>
          <Text style={styles.queueIcon}>⏳</Text>
          <View>
            <Text style={styles.queueTitle}>{pendingQueueCount} actions pending sync</Text>
            <Text style={styles.queueSubtitle}>Will upload when connection is restored</Text>
          </View>
        </View>
      )}
    </ScrollView>
  );
}

